using System.IO.Compression;
using GeoKernel.NET.WinForms;
namespace GeoKernel.ObjectDetectionInference.Winforms;
public sealed class MainForm:Form{
 const string ImagesUrl="https://github.com/geokernel-io/GeoKernel.SampleData/releases/download/v1/object_detection_images.zip",ModelUrl="https://github.com/geokernel-io/GeoKernel.SampleData/releases/download/v1/object_detection_model.zip";
 static readonly (int Id,string Name,string Color)[] Classes=[(1,"airplane","#E53935"),(2,"ship","#1E88E5"),(3,"storage_tank","#FB8C00"),(4,"baseball_diamond","#43A047"),(5,"tennis_court","#8E24AA"),(6,"basketball_court","#D81B60"),(7,"ground_track_field","#00ACC1"),(8,"harbor","#FDD835"),(9,"bridge","#3949AB"),(10,"vehicle","#6D4C41")];
 readonly GeoKernelViewerControl viewer=new(){Dock=DockStyle.Fill};readonly TextBox modelPath=new(),rasterPath=new();readonly ComboBox provider=new(){DropDownStyle=ComboBoxStyle.DropDownList};readonly Button run=new(){Text="Run object detection inference",Height=30},previous=new(){Text="Previous image"},next=new(){Text="Next image"};readonly Label position=new(){TextAlign=ContentAlignment.MiddleCenter};readonly ProgressBar progress=new(){Minimum=0,Maximum=100,Height=20};readonly Label progressText=new(){AutoSize=true};readonly TextBox details=new(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Dock=DockStyle.Fill};readonly ToolStripStatusLabel status=new();readonly GeoKernelAnalysis analysis=new();readonly List<string> images=[];AnalysisLayer? detectionLayer;int imageIndex=-1;
 public MainForm(){Text="ObjectDetectionInference";Width=1280;Height=850;Icon=new Icon(Path.Combine(AppContext.BaseDirectory,"resources","GeoKernelAppIcon.ico"));provider.Items.AddRange(["Auto","CPU","CUDA","DirectML"]);provider.SelectedIndex=0;var right=new Panel{Dock=DockStyle.Right,Width=430,Padding=new Padding(10)};var form=new TableLayoutPanel{Dock=DockStyle.Top,Height=290,ColumnCount=2,RowCount=9};form.ColumnStyles.Add(new(SizeType.Absolute,110));form.ColumnStyles.Add(new(SizeType.Percent,100));foreach(var h in new[]{24,48,34,34,30,36,32,22,22})form.RowStyles.Add(new(SizeType.Absolute,h));var title=new Label{Text="NWPU-VHR-10 object detection",AutoSize=true,Font=new Font(Font,FontStyle.Bold)};form.Controls.Add(title,0,0);form.SetColumnSpan(title,2);var desc=new Label{Text="Draw class-labelled bounding boxes as an on-the-fly layer.",AutoSize=true};form.Controls.Add(desc,0,1);form.SetColumnSpan(desc,2);AddPath(form,2,"Model package",modelPath,BrowseModel);AddPath(form,3,"Input image",rasterPath,BrowseRaster);form.Controls.Add(new Label{Text="Execution provider",AutoSize=true},0,4);provider.Dock=DockStyle.Fill;form.Controls.Add(provider,1,4);var nav=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3};nav.ColumnStyles.Add(new(SizeType.Absolute,105));nav.ColumnStyles.Add(new(SizeType.Percent,100));nav.ColumnStyles.Add(new(SizeType.Absolute,105));previous.Dock=next.Dock=position.Dock=DockStyle.Fill;nav.Controls.Add(previous,0,0);nav.Controls.Add(position,1,0);nav.Controls.Add(next,2,0);form.Controls.Add(nav,0,5);form.SetColumnSpan(nav,2);form.Controls.Add(run,0,6);form.SetColumnSpan(run,2);form.Controls.Add(progress,0,7);form.SetColumnSpan(progress,2);form.Controls.Add(progressText,0,8);form.SetColumnSpan(progressText,2);var legend=new Label{Text="airplane red · ship blue · tank orange · baseball green\r\ntennis purple · basketball pink · track cyan\r\nharbor yellow · bridge indigo · vehicle brown",Dock=DockStyle.Bottom,Height=55};right.Controls.Add(details);right.Controls.Add(new Label{Text="Inference diagnostics",Dock=DockStyle.Top,Height=22});right.Controls.Add(form);right.Controls.Add(legend);var tools=new ToolStrip{GripStyle=ToolStripGripStyle.Hidden};tools.Items.Add("Zoom In",null,(_,_)=>viewer.ZoomIn());tools.Items.Add("Zoom Out",null,(_,_)=>viewer.ZoomOut());tools.Items.Add("Full Extent",null,(_,_)=>viewer.FullExtent());tools.Items.Add("Pan",null,(_,_)=>viewer.ActiveTool=GeoKernelViewerTool.Pan);var bar=new StatusStrip();bar.Items.Add(status);Controls.Add(viewer);Controls.Add(right);Controls.Add(tools);Controls.Add(bar);viewer.ActiveTool=GeoKernelViewerTool.Pan;run.Click+=async(_,_)=>await RunInference();previous.Click+=(_,_)=>SelectImage(imageIndex-1);next.Click+=(_,_)=>SelectImage(imageIndex+1);Shown+=async(_,_)=>await PrepareSamples();FormClosed+=(_,_)=>detectionLayer?.Dispose();details.Text="Preparing sample files...";}
 static void AddPath(TableLayoutPanel p,int row,string label,TextBox box,EventHandler browse){p.Controls.Add(new Label{Text=label,AutoSize=true},0,row);var h=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};h.ColumnStyles.Add(new(SizeType.Percent,100));h.ColumnStyles.Add(new(SizeType.Absolute,78));box.Dock=DockStyle.Fill;var b=new Button{Text="Browse...",Dock=DockStyle.Fill};b.Click+=browse;h.Controls.Add(box,0,0);h.Controls.Add(b,1,0);p.Controls.Add(h,1,row);}
 void BrowseModel(object? s,EventArgs e){using var d=new FolderBrowserDialog{InitialDirectory=modelPath.Text};if(d.ShowDialog(this)==DialogResult.OK)modelPath.Text=d.SelectedPath;}void BrowseRaster(object? s,EventArgs e){using var d=new OpenFileDialog{Filter="Raster images|*.jpg;*.jpeg;*.png;*.tif;*.tiff"};if(d.ShowDialog(this)==DialogResult.OK){rasterPath.Text=d.FileName;OpenSource(d.FileName);}}
 async Task PrepareSamples(){run.Enabled=false;try{var root=Path.Combine(AppContext.BaseDirectory,"data");var first=await EnsureSample(ImagesUrl,root,"object-detection-images","1.jpg","images");var manifest=await EnsureSample(ModelUrl,root,"object-detection-model","geokernel-model.json","model");images.AddRange(Directory.GetFiles(Path.GetDirectoryName(first)!,"*.jpg").OrderBy(x=>int.Parse(Path.GetFileNameWithoutExtension(x))));EnsurePixelWorldFiles(images);modelPath.Text=Path.GetDirectoryName(manifest)!;SelectImage(0);details.Text=$"{images.Count} images and the ONNX model are ready.";SetProgress(0,"Ready");}catch(Exception ex){details.Text="Sample preparation failed:\r\n"+ex.Message;MessageBox.Show(this,ex.Message,Text);}finally{run.Enabled=true;}}
 async Task<string> EnsureSample(string url,string root,string folder,string required,string label){var dir=Path.Combine(root,folder);var target=Path.Combine(dir,required);if(File.Exists(target))return target;Directory.CreateDirectory(dir);var zip=Path.Combine(root,folder+".zip");using var client=new HttpClient();using var response=await client.GetAsync(url,HttpCompletionOption.ResponseHeadersRead);response.EnsureSuccessStatusCode();var total=response.Content.Headers.ContentLength;await using(var input=await response.Content.ReadAsStreamAsync())await using(var output=File.Create(zip)){var buffer=new byte[128*1024];long received=0;int read;while((read=await input.ReadAsync(buffer))>0){await output.WriteAsync(buffer.AsMemory(0,read));received+=read;if(total>0)SetProgress((int)(received*100/total),$"Downloading {label}...");}}SetProgress(100,$"Extracting {label}...");ZipFile.ExtractToDirectory(zip,dir,true);File.Delete(zip);return File.Exists(target)?target:throw new FileNotFoundException(required);}
 static void EnsurePixelWorldFiles(IEnumerable<string> files){const string world="1\r\n0\r\n0\r\n-1\r\n0.5\r\n-0.5\r\n";foreach(var image in files){var sidecar=Path.ChangeExtension(image,".jgw");if(!File.Exists(sidecar))File.WriteAllText(sidecar,world);}}
 void SelectImage(int index){if(index<0||index>=images.Count)return;imageIndex=index;rasterPath.Text=images[index];position.Text=$"{index+1} / {images.Count} — {Path.GetFileName(images[index])}";previous.Enabled=index>0;next.Enabled=index+1<images.Count;OpenSource(images[index]);}void OpenSource(string path){detectionLayer?.Dispose();detectionLayer=null;viewer.ClearLayers();if(!viewer.AddLayerFile(path))throw new InvalidOperationException("Source image could not be opened.");viewer.FullExtent();}
 async Task RunInference(){if(!Directory.Exists(modelPath.Text)||!File.Exists(rasterPath.Text))return;run.Enabled=false;SetProgress(0,"Running tiled object detection...");try{var layer=await analysis.RunAiObjectDetectionToMemoryAsync(new(){ModelPackagePath=modelPath.Text,RasterPath=rasterPath.Text,Provider=Enum.Parse<AIExecutionProvider>(provider.Text),LayerName="object_detections",WindowSize=512,Overlap=256,NmsThreshold=0.3},new Progress<AiObjectDetectionProgress>(x=>SetProgress(x.Percent,x.Message)));var d=layer.Diagnostics;var count=d.GetProperty("materializedCount").GetInt64();var tiles=$"{d.GetProperty("tilesProcessed").GetInt32()} ({d.GetProperty("tilesX").GetInt32()} x {d.GetProperty("tilesY").GetInt32()})";detectionLayer?.Dispose();detectionLayer=null;viewer.ClearLayers();viewer.AddLayerFile(rasterPath.Text);if(count>0){detectionLayer=layer;layer.AddTo(viewer);var style=DetectionStyle("#FF4020");viewer.SetLayerStyle(0,style);viewer.SetLayerCategorizedRenderer(0,"class_id",Classes.Select(x=>new GeoKernelCategorizedSymbolClass{Value=x.Id,Label=x.Name,Style=DetectionStyle(x.Color)}),style);}else layer.Dispose();viewer.RefreshLayers();viewer.FullExtent();details.Text=$"GeoKernel AI tiled object detection\r\n\r\nProvider: {provider.Text}\r\nWindow: 512, overlap: 256, NMS: 0.3\r\nTiles processed: {tiles}\r\nDetections: {count}\r\nVector output: {(count>0?"in-memory layer":"no detections")}";SetProgress(100,count>0?"Inference complete":"Inference complete — no detections");}catch(Exception ex){SetProgress(0,"Inference failed");details.Text="Inference failed:\r\n"+ex.Message;MessageBox.Show(this,ex.Message,Text);}finally{run.Enabled=true;}}
 static GeoKernelLayerStyle DetectionStyle(string color)=>new(){FillColor=color,FillOpacity=90,LineColor=color,LineWidth=1.5,ShowLabels=true,LabelField="label",LabelFontSize=11,LabelColor="#FFFFFF",LabelHaloEnabled=true,LabelHaloColor="#202020",LabelHaloWidth=2,LabelAllowOverlap=true};void SetProgress(int value,string text){progress.Value=Math.Clamp(value,0,100);progressText.Text=$"{progress.Value}% — {text}";status.Text=text;}
}
